package cronadapter_test

import (
	"io"
	"log/slog"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	cronadapter "github.com/ymedword/basalt/internal/adapters/cron"
)

// 本文件是 cron 封装的专属验收（颗粒度文档 §3.2.1 第 24 行：9 函数 / 14 例）。
// 固定向量按 IANA 时区规则独立算出后写成字面量（D-16：不得在测试运行时用同一个
// `Next()` 生成期望值，否则等于拿实现验证实现）；robfig 实跑只用于核验。
// The cron adapter suite: expected occurrence lists are literal values computed
// independently from the IANA rules (D-16), never generated by the same Next().

// newTestEngine 造一个丢弃日志的引擎（用例不判日志内容）。
// newTestEngine builds an engine with a discarded logger.
func newTestEngine() *cronadapter.Engine {
	return cronadapter.New(slog.New(slog.NewTextHandler(io.Discard, nil)))
}

// occurrencesUTC 把 Occurrences 的返回值统一渲染成 UTC RFC3339 字符串——
// 与字面量期望值逐字比较，不受返回时刻的 Location 影响。
// occurrencesUTC renders the result as UTC RFC3339 strings for literal comparison.
func occurrencesUTC(e *cronadapter.Engine, spec string, from, to time.Time, limit int) []string {
	got := e.Occurrences(spec, from, to, limit)
	out := make([]string, 0, len(got))
	for _, at := range got {
		out = append(out, at.UTC().Format(time.RFC3339))
	}
	return out
}

// TestEngine_RejectsFiveFieldSpec —— 约束 4 / 5：6 段解析器必须拒绝 5 段表达式。
// 逆改点：解析器退化为 5 段（`cron.Minute|cron.Hour|...`）→ 本用例 `Add` 成功，断言红。
func TestEngine_RejectsFiveFieldSpec(t *testing.T) {
	e := newTestEngine()

	_, err := e.Add("CRON_TZ=UTC 0 8 * * *", func() {})
	require.Error(t, err, "5 段表达式不得注册（6 段制式，约束 4 / 5）")
}

// TestEngine_RejectsMissingCRONTZ —— 约束 5：无 `CRON_TZ=` 前缀的 spec 必须拒绝。
// robfig 缺省按进程本地时区解释，放行即把服务器时区带进触发。
// 逆改点：不校验前缀 → `Add` 成功，断言红。
func TestEngine_RejectsMissingCRONTZ(t *testing.T) {
	e := newTestEngine()

	_, err := e.Add("0 0 8 * * *", func() {})
	require.Error(t, err, "缺少 CRON_TZ= 前缀不得注册（约束 5）")
	require.Contains(t, err.Error(), "CRON_TZ", "错误必须点名缺失的前缀")
}

// TestEngine_ParsesSixFieldWithCRONTZ —— 约束 5：6 段 + `CRON_TZ=` 前缀正常注册。
func TestEngine_ParsesSixFieldWithCRONTZ(t *testing.T) {
	e := newTestEngine()

	h, err := e.Add("CRON_TZ=Asia/Shanghai 0 0 8 * * *", func() {})
	require.NoError(t, err)
	require.NotNil(t, h)
	h.Stop()
}

// TestEngine_OccurrencesFromFixedStart —— 约束 5 / TD §6.3 / agent-md §3.1：
// 契约三样例（固定起点 2026-10-01T00:00:00Z）+ 两条 DST 边界样例。
// 期望值全部为独立算出的字面量（D-16）；DST 行分别留"跳过"与"重复"的证据。
func TestEngine_OccurrencesFromFixedStart(t *testing.T) {
	e := newTestEngine()
	from := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)

	t.Run("shanghai_daily_0800", func(t *testing.T) {
		// 上海每日 08:00（+08:00）= 00:00Z；固定起点恰为当日触发点，Next 严格取其后。
		want := []string{
			"2026-10-02T00:00:00Z", "2026-10-03T00:00:00Z", "2026-10-04T00:00:00Z",
			"2026-10-05T00:00:00Z", "2026-10-06T00:00:00Z", "2026-10-07T00:00:00Z",
			"2026-10-08T00:00:00Z", "2026-10-09T00:00:00Z", "2026-10-10T00:00:00Z",
			"2026-10-11T00:00:00Z",
		}
		got := occurrencesUTC(e, "CRON_TZ=Asia/Shanghai 0 0 8 * * *",
			from, time.Date(2026, 10, 20, 0, 0, 0, 0, time.UTC), 10)
		require.Equal(t, want, got)
	})

	t.Run("utc_sunday_2330", func(t *testing.T) {
		// 每周日 23:30 UTC；2026-10-01 是周四，首个周日为 10-04。
		want := []string{
			"2026-10-04T23:30:00Z", "2026-10-11T23:30:00Z", "2026-10-18T23:30:00Z",
			"2026-10-25T23:30:00Z", "2026-11-01T23:30:00Z", "2026-11-08T23:30:00Z",
			"2026-11-15T23:30:00Z", "2026-11-22T23:30:00Z", "2026-11-29T23:30:00Z",
			"2026-12-06T23:30:00Z",
		}
		got := occurrencesUTC(e, "CRON_TZ=UTC 0 30 23 * * 0",
			from, time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC), 10)
		require.Equal(t, want, got)
	})

	t.Run("shanghai_every_six_hours", func(t *testing.T) {
		// 上海 00/06/12/18 点整 = 16:00Z / 22:00Z / 04:00Z / 10:00Z；
		// 起点 00:00Z = 上海 08:00，其后最近整点为 12:00 +08 = 04:00Z。
		want := []string{
			"2026-10-01T04:00:00Z", "2026-10-01T10:00:00Z", "2026-10-01T16:00:00Z",
			"2026-10-01T22:00:00Z", "2026-10-02T04:00:00Z", "2026-10-02T10:00:00Z",
			"2026-10-02T16:00:00Z", "2026-10-02T22:00:00Z", "2026-10-03T04:00:00Z",
			"2026-10-03T10:00:00Z",
		}
		got := occurrencesUTC(e, "CRON_TZ=Asia/Shanghai 0 0 */6 * * *",
			from, time.Date(2026, 10, 20, 0, 0, 0, 0, time.UTC), 10)
		require.Equal(t, want, got)
	})

	t.Run("dst_spring_forward_skips_nonexistent_time", func(t *testing.T) {
		// America/New_York 2027-03-14 02:00→03:00：当地 02:30 不存在（独立换算证实），
		// 当日的触发被跳过——03-13 07:30Z（EST）与 03-15 06:30Z（EDT）之间相隔 47 小时。
		want := []string{
			"2027-03-13T07:30:00Z",
			"2027-03-15T06:30:00Z",
			"2027-03-16T06:30:00Z",
		}
		got := occurrencesUTC(e, "CRON_TZ=America/New_York 0 30 2 * * *",
			time.Date(2027, 3, 13, 0, 0, 0, 0, time.UTC),
			time.Date(2027, 3, 16, 12, 0, 0, 0, time.UTC), 10)
		require.Equal(t, want, got, "春令时当日 02:30 被跳过")
	})

	t.Run("dst_fall_back_repeats_local_time", func(t *testing.T) {
		// America/New_York 2027-11-07 02:00 EDT→01:00 EST：当地 01:30 出现两次
		// （05:30Z 为 EDT、06:30Z 为 EST），两次都必须枚举出来。
		want := []string{
			"2027-11-06T05:30:00Z",
			"2027-11-07T05:30:00Z",
			"2027-11-07T06:30:00Z",
			"2027-11-08T06:30:00Z",
		}
		got := occurrencesUTC(e, "CRON_TZ=America/New_York 0 30 1 * * *",
			time.Date(2027, 11, 6, 0, 0, 0, 0, time.UTC),
			time.Date(2027, 11, 8, 12, 0, 0, 0, time.UTC), 10)
		require.Equal(t, want, got, "秋令时回落的 01:30 出现两次")
	})
}

// TestEngine_OccurrencesCapsAtLimit —— 约束 38：枚举最多取 limit 个（调用方上限 1000）。
func TestEngine_OccurrencesCapsAtLimit(t *testing.T) {
	e := newTestEngine()
	from := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)

	got := e.Occurrences("CRON_TZ=UTC * * * * * *", from, from.Add(time.Hour), 1000)
	require.Len(t, got, 1000, "每秒一次、窗口一小时，但仍以 limit=1000 封顶")
}

// TestEngine_OccurrencesNoMoreTimes —— 枚举到 `to` 截止，不无限循环。
func TestEngine_OccurrencesNoMoreTimes(t *testing.T) {
	e := newTestEngine()
	from := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)

	require.Empty(t, e.Occurrences("CRON_TZ=UTC 0 0 8 * * *", from, from.Add(time.Hour), 1000),
		"窗口内没有触发点 → 空结果、不阻塞")

	got := e.Occurrences("CRON_TZ=UTC * * * * * *", from, from.Add(5*time.Second), 1000)
	require.Len(t, got, 5, "每秒一次、含 to 本秒，窗口 5 秒恰 5 个")
}

// TestEngine_AddAndStop —— 句柄停止单个任务；同 spec 的多任务可并存。
func TestEngine_AddAndStop(t *testing.T) {
	t.Run("handle_stops_job", func(t *testing.T) {
		e := newTestEngine()
		fired := make(chan struct{}, 8)
		h, err := e.Add("CRON_TZ=UTC * * * * * *", func() { fired <- struct{}{} })
		require.NoError(t, err)
		e.Start()

		select {
		case <-fired:
		case <-time.After(5 * time.Second):
			t.Fatal("任务未在 5 秒内触发")
		}
		h.Stop()

		// 清掉停止前后可能已排队的触发，再跨过一个完整 tick 断言不再触发。
		for {
			select {
			case <-fired:
				continue
			default:
			}
			break
		}
		select {
		case <-fired:
			t.Fatal("句柄停止后任务仍在触发")
		case <-time.After(1500 * time.Millisecond):
		}
		<-e.Stop().Done()
	})

	t.Run("same_spec_two_jobs", func(t *testing.T) {
		e := newTestEngine()
		firedA := make(chan struct{}, 4)
		firedB := make(chan struct{}, 4)
		_, err := e.Add("CRON_TZ=UTC * * * * * *", func() { firedA <- struct{}{} })
		require.NoError(t, err)
		_, err = e.Add("CRON_TZ=UTC * * * * * *", func() { firedB <- struct{}{} })
		require.NoError(t, err)
		e.Start()
		defer func() { <-e.Stop().Done() }()

		for name, ch := range map[string]chan struct{}{"A": firedA, "B": firedB} {
			select {
			case <-ch:
			case <-time.After(5 * time.Second):
				t.Fatalf("同 spec 的任务 %s 未触发", name)
			}
		}
	})
}

// TestEngine_StopWaitsForJobs —— `Stop` 返回的 ctx 在在途 job 结束后才关闭。
func TestEngine_StopWaitsForJobs(t *testing.T) {
	e := newTestEngine()
	started := make(chan struct{})
	release := make(chan struct{})
	var once sync.Once
	_, err := e.Add("CRON_TZ=UTC * * * * * *", func() {
		once.Do(func() { close(started) })
		<-release
	})
	require.NoError(t, err)
	e.Start()

	select {
	case <-started:
	case <-time.After(5 * time.Second):
		t.Fatal("任务未在 5 秒内触发")
	}

	ctx := e.Stop()
	select {
	case <-ctx.Done():
		t.Fatal("在途 job 未结束，Stop 的 ctx 不得关闭")
	case <-time.After(100 * time.Millisecond):
	}

	close(release)
	select {
	case <-ctx.Done():
	case <-time.After(5 * time.Second):
		t.Fatal("job 结束后 Stop 的 ctx 仍未关闭")
	}
}

// TestEngine_UnknownZoneFails —— 未知时区在解析期失败（Add 返回错误）。
func TestEngine_UnknownZoneFails(t *testing.T) {
	e := newTestEngine()

	_, err := e.Add("CRON_TZ=Not/AZone 0 0 8 * * *", func() {})
	require.Error(t, err, "未知时区不得注册")
}
